/* أدعية مختارة من كتيّب «فإنك بأعيننا»، مرتبة على مواضيعه الثلاثين. آيات
   القرآن في المواضيع لا تُكتب هنا، فهي تُقرأ من المصحف في التطبيق نفسه. */
var DUA_BOOK = [
  { id: 'rizq', n: 'الرزق', i: [
    'اللهم زدنا ولا تنقصنا، وأكرمنا ولا تهنا، وأعطنا ولا تحرمنا، وآثرنا ولا تؤثر علينا، وأرضنا وارض عنا',
    'اللهم إني أسألك علما نافعا، ورزقا طيبا، وعملا متقبلا',
    'يا الله، يا الله، يا الله، أسألك بحق من حقه عليك عظيم أن تصلي على محمد وآل محمد وأن ترزقني العمل بما علمتني من معرفة حقك وأن تبسط علي ما حظرت من رزقك',
    'اللهم مالك الملك، تؤتي الملك من تشاء، وتنزع الملك ممن تشاء، وتعز من تشاء، وتذل من تشاء، بيدك الخير، إنك على كل شيء قدير، رحمن الدنيا والآخرة ورحيمهما، تعطيهما من تشاء، وتمنع منهما من تشاء، ارحمني رحمة تغنيني بها عن رحمة من سواك',
    'اللهم أكثر مالي، وولدي، وبارك لي فيما أعطيتني',
    'اللهم اجعلني أتبوأ من أرضك حيث أشاء',
    'اللهم رزقا لا ينفد',
    'رب ارزقني وارزق مني',
    'بارك لي فيما رزقتني وقنعني فيه',
    'اللهم وسع من أسباب الحلال أرزاقنا.. ووجه في أبواب البر إنفاقنا.. واحجب عنا من الأرزاق ما يكون فسادا لقلوبنا وعقولنا',
    'اللهم ما زويت عنا من متاع الدنيا الفانية فادخره لنا في خزائنك الباقية.. واجعل ما مددتنا به من متاعها زادا إلى حسن لقائك.. ووصلا إلى قربك',
    'واجعلني ذا حظ عظيم',
    'اللهم جودك الذي عودتني',
    'اللهم إن كان رزقي في السماء فأنزله، وإن كان في الأرض فأخرجه، وإن كان بعيدا فقربه وإن كان قريبا فيسره، وإن كان قليلا فكثره، وإن كان كثيرا فبارك لي فيه',
    'اللهم أغننا بحلالك عن حرامك، وتولنا فأنت أرحم الراحمين',
    'اللهم يا رازق السائلين، يا راحم المساكين، ويا ذا القوة المتين، ويا خير الناصرين، يا ولي المؤمنين، يا غياث المستغيثين، إياك نعبد وإياك نستعين، اللهم إني أسألك رزقا واسعا طيبا من رزقك',
    'اللهم ارزقني رزقا واسعا حلالا طيبا من غير كد، واستجب دعائي من غير رد',
    'وأعوذ بك اللهم من درب مسدود، وسعي مردود، وظن مخذول وأن يتعلق قلبي بما ليس لي',
    'اللهم اجعل لنا نصيبا في سعة الأرزاق وتيسير الأحوال وقضاء الحاجات وإجابة الدعوات',
    'اللهم آت قلبي سؤله واجعل ما أسعى إليه يسعى إلي إنك على كل شيء قدير',
    'اللهم ارزقني رزقا لا تجعل لأحد فيه منة ولا في الآخرة عليه تبعة برحمتك يا أرحم الراحمين',
    'اللهم صب علينا الخير صبا صبا ولا تجعل عيشنا كدا كدا',
    'اللهم اكتب لنا من خيرك ما لا يخطر ببالنا وارزقنا من حيث لا نحتسب',
    'اجعل يا رب رزقك لي واسعا، ومطلبه سهلا، ومأخذه قريبا، ولا تعنني بطلب ما لم تقدر لي فيه رزقا',
  ] },
  { id: 'baraka', n: 'البركة', i: [
    'اللهم إني أسألك خير المسألة وخير الدعاء وخير النجاح اللهم بارك لي في الرزق وفي الولد وفي الجسم وفي القلب اللهم ارزقنا البركة في كل شيء اللهم بارك لي في كل عمل أعمله وبالطريقة التي أعمل بها اللهم إني أسألك البركة في الوقت والجهد والرزق، اللهم لا حول ولا قوة لي إلا بك اللهم بركة أينما كنا وحللنا وقلبا منيرا مشرقا اللهم إني أسألك بركة تطهر بها قلبي، وتصلح بها أمري، وتذهب بها شري، وتجلو بها حزني، وتجمع بها شملي وارزقني بركة الخطى وسدادها، وأعذني من أن تزل قدمي بعد ثبوتها اللهم ارزقنا بركة في العمر، ونورا في القلب، وضياء في الوجه، وسعة في الرزق، وثباتا على الحق ورضا في النفس اللهم ارزقنا بركة الوقت، وانفتاح العقل، وانشراح الصدر اللهم لا تقطع رحمتك عنا، وأعطنا ولا تحرمنا، جد علينا بمغفرة، وبركة وقبول',
    'اللهم إنا نسألك بركة تطهر بها قلوبنا وتغفر ذنوبنا وتصلح أمورنا وتكشف همومنا',
    'ربنا امنحنا من بركة الأعمار ما نجوز به من سبقنا، وبلغنا بفضلك ما بلغ الباذلون بجهدهم، وارزقنا عملا صالحا، وعلما نافعا نزداد به إيمانا وخشية',
    'اللهم بارك لنا في يومنا واجعله شاهدا لنا لا علينا، رب متعنا براحة البال وصلاح الحال وقبول الأعمال وصحة الأبدان',
    'اللهم بارك لنا في سعينا',
    'اللهم اغفر لي ما مضى وبارك لي فيما هو آت',
    'اللهم ارزقني البركة في كل شيء اللهم بارك لي في رزقي ونفسي وجسدي وعمري ووقتي وزدني خيرا فوق خير يا رب',
    'بارك لنا يا الله في الخطوة والقرار والمصير',
    'اللهم بارك لنا في الذرية ووفقهم لطاعتك وارزقهم حظا في الدين والعلم والخلق يا رب العالمين',
    'اللهم بارك لنا في ذكرك ولا تشغلنا بغيرك ووفقنا لحمدك وشكرك وأدم علينا عفوك وسترك، وعافيتك يا رب العالمين',
    'اللهم البركة التي تثمر في أعمارنا وأعمالنا وأيامنا',
    'اللهم اقسم لنا البركة والقبول والرضا في حياتنا',
    'اللهم البركة والخير في كل اتجاه',
    'اللهم بركة في الأرض وقبولا في السماء',
    'اللهم سخر لنا من الأقدار أجملها ومن البركة أتمها، ومن حوائج الدنيا أيسرها',
    'اللهم افتح لنا أبواب البركة',
    'اللهم بارك لي وبارك ما حولي، واجعل البركة في طريقي وقتي وقولي وفعلي',
    'يا رب بركة في العمر والعلم والوقت والرزق، ونور في كل رحلة ومرحلة، ورضا في الخيارات والقرارات والعلاقات، وسلام مع الأقدار والأعمار، وحياة في تفاصيل الحياة',
  ] },
  { id: 'taysir', n: 'التسخير والتيسير', i: [
    'اللهم إني أسألك القبول بين الخلق وأن تسخر لي ملائكتك وجنود أرضك وكل من وليته أمري',
    'اللهم بلطيف صنعك في التسخير وخفي لطفك في التيسير الطف بي فيما جرت به المقادير واصرف عني السوء إنك على كل شيء قدير، اللهم لا تكلني لنفسي فأعجز عن التدبير ولا لأحد من خلقك وأجزع، وتداركني بلطفك يا من لا تدركه الأبصار وهو يدرك الأبصار وهو اللطيف الخبير',
    'اللهم يسر لي الخير حيث كنت وحيث توجهت، اللهم سخر لي الأرزاق والفتوحات في كل وقت وساعة ويسر علي كل صعب وهون علي كل عسير واحفظني بما ينزل من السماء وما يخرج منها وما يرى عليها',
    'اللهم لا سهل إلا ما جعلته سهلا وأنت تجعل الحزن إذا شئت سهلا',
    'يا رب سخر لي حظا ونصيبا يتعجب منه أهل السماوات والأرض، تسخير ونصيب يليق بجلالك وقدرتك وكرمك يا أرحم وأكرم الأكرمين',
    'اللهم سخر لي جميع خلقك كما سخرت البحر لسيدنا موسى عليه السلام وألن لي قلوبهم كما ألنت الحديد لداوود عليه السلام فإنهم لا ينطقون إلا بإذنك، نواصيهم في قبضتك وقلوبهم في يديك تصرفها كيف شئت',
    'اللهم يا مغير الأحوال غير حالنا إلى أحسن حال، وسخر لنا من حظوظ الدنيا ما تعلم أنه خير لنا واصرف عنا كل ما هو شر لنا إنك على كل شيء قدير',
    'اللهم سخر لي من حظوظ الدنيا ما لا عين رأت ولا أذن سمعت ولا خطر على قلب بشر',
    'اللهم سخر لنا من الجبر والعوض ما ينسينا ويسعدنا ويرضينا',
    'اللهم يا عظيم السلطان، يا قديم الإحسان يا دائم النعماء، يا باسط الرزق، يا كثير الخيرات، يا واسع العطاء، يا دافع البلاء، يا سامع الدعاء، يا حاضرا ليس بغائب يا موجودا عند الشدائد، يا خفي اللطف، يا حليما لا يعجل، اللهم الطف بنا في تيسير كل أمر عسير فإن تيسير العسير عليك يسير فنسألك التيسير والمعافاة في الدنيا والآخرة',
    'يا رب اجعلني ممن تحب وسخرني لما تحب وسخر لي من تحب',
    'يا الله إن اليسر جند من جنودك فسخره لي وأيدني به',
    'يا رب كما سيرت الجبال سير لي رزقي ونصيبي وأكرمني بكرمك وأعطني ما أتمنى',
    'اللهم ارفع عني حمل التفكير والترتيب، ودبر لي أمري فإني لا أحسن التدبير',
    'وتوفني وأنت راض عني وسخر لي من يدعو لي بعد وفاتي',
    'يا رب سخر لنا حظا ونصيبا يتعجب منه أهل السماء والأرض، تسخير ونصيب يليق بجلالك وقدرتك وكرمك يا أرحم وأكرم الأكرمين',
    'اللهم سخر لي ملائكة السماء برحمتك وجنود الأرض بقدرتك وكل من وليته أمري',
    'يا رب سخر لي أحبابك ويسر لي أسبابك واجزني خير ثوابك وكن لي حبيبا وقريبا ولدعائي مجيبا وارض عني رضا لا أحزن بعده أبدا',
    'اللهم التيسير واليسر والمسرة',
    'اللهم وفقنا فإن التوفيق من عندك ويسر لنا، فإن التيسير لطفك',
    'اللهم إني أسألك التيسير والسداد والبركة والتوفيق في أمورنا وأيامنا',
    'اللهم أنت الميسر يسر أمورنا وأمور أحبتنا يا رب',
    'فنسألك التيسير والمعافاة في الدنيا والآخرة',
    'اللهم إني أسألك التيسير لأموري وأن تجعل التوفيق حليفي اللهم إني وكلتك أمري فأنت خير وكيل',
    'اللهم دبر لنا ما نجهله ويسر لنا ما نأمله وقرب لنا ما نرقبه وهب لنا نورا يضيء حياتنا وتولنا فيمن توليت',
    'اللهم سهل علي كل ما هو آت.. ويسر لي جميع أموري.. واجعل الخير دائما فيما اخترت لي',
    'اللهم يسر لنا الهدى والتقى والعفاف والغنى واجعلنا من الراشدين، اللهم اكتب لنا الخيرات والمسرات وأعنا على شر أنفسنا وأعنا على فعل الخيرات',
    'اللهم اشرح لي صدري ويسر لي أمري',
    'يا مسخر الأقدار سخر لي من الأقدار ما تسر به نفسي إنك على كل شيء قدير',
  ] },
  { id: 'salam', n: 'السلام', i: [
    'اللهم ارزقنا طيب المقام، وحسن الختام، ودار السلام',
    'اللهم أنت السلام ومنك السلام، تباركت ذا الجلال والإكرام',
    'اللهم ألف بين قلوبنا، وأصلح ذات بيننا، واهدنا سبل السلام، ونجنا من الظلمات إلى النور',
    'اللهم أنت السلام ومنك السلام فسلم قلوبنا من أذى الدنيا وحزن الأيام',
    'اللهم رب السلام هادي الأنام، أنزل طمأنينتك على كل قلب',
    'اللهم ألف بين قلوبنا، وأصلح ذات بيننا، واهدنا سبل السلام، ونجنا من الظلمات إلى النور',
    'يا رب امنحني السلام لأكمل مسيرتي في الحياة بكامل الرضا ولا تكلني إلي، وكلني إليك، وكن معي وسيرني دروبا من اختيارك يا رب',
    'اللهم هون علينا سعينا في مناكب الحياة، واطو عنا بعد الغاية، وامنحنا نعمة اليقظة واليقين، وازرع في قلوبنا السكينة والهدوء وحب السلام',
    'اللهم ارزقنا السلام الذي يزهر بنا ويدلنا إليك',
    'اللهم إني أسألك أن تحملنا الحياة إلى مسراتها، أن نبقى لامعين جدا، محفوفين بالمحبة والقبول، ننعم بمزيد من الحياة الهادئة، السلام، وصفاء البال',
    'اللهم إني أسألك الثبات في الأمر والعزيمة على الرشد وأسألك موجبات رحمتك وعزائم مغفرتك وأسألك شكر نعمتك وحسن عبادتك وأسألك قلبا سليما ولسانا صادقا وأسألك من خير ما تعلم وأعوذ بك من شر ما تعلم وأستغفرك لما تعلم إنك أنت علام الغيوب',
    'اللهم إني أسألك السلام، سلام الروح، سلام القلب، سلام العقل وسلام المسير',
    'اللهم اغسل قلوبنا بماء السلام فلا حقد ولا حسد ولا شحناء وارونا منه في عطش البغضاء وأمنا من أنفسنا وفي أنفسنا، وأمنا في هواجسنا ومن هواجسنا وأمنا في أهلينا وما أكسبتنا إياه',
    'يا سلام سلمنا منك وسلمنا لك بأرق ألطافك وألطف أسمائك',
    'اللهم أنت السلام ومنك السلام سلمني من الدنيا ومن نفسي ومن رجاء الأشياء دون نيلها',
  ] },
  { id: 'ghina', n: 'الغنى', i: [
    'اللهم أغنني بحلالك عن حرامك، وأغنني بفضلك عمن سواك. اللهم ارزقني رزقا حلالا طيبا مباركا فيه. وعجل لي به وأنت نعم المجيب',
    'اللهم مالك الملك، تؤتي الملك من تشاء، وتنزع الملك ممن تشاء، وتعز من تشاء، وتذل من تشاء، بيدك الخير، إنك على كل شيء قدير، رحمن الدنيا والآخرة ورحيمهما، تعطيهما من تشاء، وتمنع منهما من تشاء، ارحمني رحمة تغنيني بها عن رحمة من سواك',
    'اللهم رب السماوات ورب الأرض ورب العرش العظيم، ربنا ورب كل شيء، فالق الحب والنوى ومنزل التوراة والإنجيل والفرقان، أعوذ بك من شر كل شيء أنت آخذ بناصيته، اللهم أنت الأول فليس قبلك شيء وأنت الآخر فليس بعدك شيء، وأنت الظاهر فليس فوقك شيء، وأنت الباطن فليس دونك شيء اقض عنا الدين وأغننا من الفقر',
    'اللهم صن وجهي باليسار ولا تبذل جاهي بالإقتار فأسترزق رزقك من غيرك، وأستعطف شرار خلقك، وأبتلى بحمد من أعطاني، وأفتن بذم من منعني، وأنت من وراء ذلك كله ولى الإجابة والمنع',
    'رب لا تكلني إلى أحد ولا تحوجني إلى أحد، أسألك الغنى عن كل أحد، فأنت وحدك عليك المستند وعليك المعتمد، أنت الواحد الفرد الصمد، لا شريك لك ولا ولد، أسألك أن تأخذ بيدي من الضلال إلى الرشد، وأن تنجيني من الضيق والنكد',
    'يا رب منك الغنى وبك استغنى عمن سواك',
    'يا رب تول عبادك الساعين إليك، فمنك الهدى، ومنك الغنى، ومنك التوفيق، ومنك الرضا',
    'ما لنا رب سواك ندعوه أنت القريب لمن ناجاك.. وأنت المجيب لمن دعاك أنت الغني ونحن الفقراء إليك ارحمنا برحمتك التي وسعت كل شيء',
    'اللهم انزع من قلبي كل ما يغضبك عني أغنني بك وبحلالك آوني إليك ولركنك آنسني بك وبذكرك لا إله إلا أنت، قلبي بيدك ماض في حكمك، أسألك برد الرضا وكمال الغنى بك',
    'اللهم إني أعوذ بك من الفقر والقلة والذلة، وأعوذ بك أن أظلم أو أظلم',
  ] },
  { id: 'janna', n: 'الجنة', i: [
    'يا رب إني أسألك الثمانية أبواب، وأن لا يؤصد في وجهي بابا، اللهم أدخلنى جنتك من حيث ما أريد، يا رب افتح أبوابك لي ما علمت وما لم أعلم',
    'اللهم إني أسألك الجنة وما قرب إليها من قول وعمل، وأعوذ بك من النار وما قرب إليها من قول وعمل، وأعوذ بك أن أقول زورا أو أغشى فجورا أو أكون بك مغرورا',
    'اللهم إني أسألك بأن لك الحمد لا إله إلا أنت وحدك لا شريك لك المنان يا بديع السماوات والأرض يا ذا الجلال والإكرام يا حي يا قيوم إني أسألك الجنة وأعوذ بك من النار، اللهم ألبسني العافية حتى أهنأ بالمعيشة، واختم لي بالمغفرة حتى لا تضرني الذنوب، واكفني كل هول دون الجنة حتى تبلغنيها برحمتك يا أرحم الراحمين اللهم خفف عنا ثقل أوزارنا، وارزقنا عيشة الأبرار، واكفنا واصرف عنا شر الأشرار، وأعتق رقابنا ورقاب آبائنا وأمهاتنا وعشيرتنا من عذاب القبر ومن النيران، برحمتك يا أرحم الراحمين',
    'اللهم إني أسألك النعيم يوم العيلة، والأمن يوم الخوف، وأعوذ بك من شر ما أعطيتنا، وشر ما منعتنا',
    'اللهم ارزقنا الجنة بلا حساب ولا سابقة عذاب، اللهم ارزقنا جنة عرضها السماوات والأرض واغفر لنا خطايانا ولا تقبض أرواحنا إلا وأنت راض عنا، يا رب إنا نسألك حسن الخاتمة',
    'اللهم ارزقنا الجنة بغير حساب ولا سابق عذاب، اللهم اجعلنا من ورثة جنة النعيم، اللهم ارزقنا لذة النظر إلى وجهك الكريم',
    'اللهم ارزقنا الجنة ووالدينا ومن نحب ومن فقدنا والمسلمين جميعا وارزقنا يا الله شفاعة نبينا محمد',
    'اللهم ارزقنا الجنة ونعيمها وخلودها مع من نحب وأعتق رقابنا ووالدينا من النار، اللهم أدخلنا جنات الفردوس الأعلى بغير حساب ولا سابق عذاب اللهم إني أسألك الجنة لي ولوالدي ولإخوتي ولجميع أحبتي وجميع المسلمين الأحياء منهم والأموات',
    'اللهم اكتبنا من عتقائك من النار، اللهم أعتق رقابنا من النار، اللهم أعتق رقابنا من النار، يا عزيز يا غفار، يا ذا الجلال والإكرام اغفر لنا يا إلهنا، وارحمنا فإنك بنا راحم، ولا تعذبنا فإنك علينا قادر، ربنا لا تزغ قلوبنا بعد إذ هديتنا وهب لنا من لدنك رحمة إنك أنت الوهاب، اصرف عنا عذاب جهنم، ربنا اصرف عنا عذاب جهنم إن عذابها كان غراما، إنها ساءت مستقرا ومقاما',
    'اللهم اقسم لنا من خشيتك ما يحول بيننا وبين معاصيك، ومن طاعتك ما تبلغنا به جنتك، ومن اليقين ما يهون علينا مصائب الدنيا، ومتعنا بأسماعنا وأبصارنا وقوتنا ما أحييتنا، واجعله الوارث منا، واجعل ثأرنا على من ظلمنا، وانصرنا على من عادانا، ولا تجعل مصيبتنا في ديننا، ولا تجعل الدنيا أكبر همنا، ولا مبلغ علمنا، ولا تسلط علينا من لا يرحمنا',
    'اللهم يا خير من سئل، ويا أجود من أعطى، ويا أكرم من عفا، ويا أعظم من غفر، ويا أعدل من حكم، أسألك بأن ترزقني الجنة وما يقرب إليها من قول أو عمل، وأعوذ بك من النار وما يقرب إليها من قول أو عمل',
    'اللهم يا أوفى من وعد ويا أبصر من راقب ويا أسرع من حاسب ويا أرحم من عاقب ويا أحسن من خلق ويا أحكم من شرع ويا أحق من عبد ويا أولى من دعي أسألك الفردوس الأعلى من الجنة',
    'اللهم ارحمني إذا حان أجلي اللهم اغفر لي إن اقترب يومي اللهم الجنة إن ذهبت الروح إليك',
    'اللهم إني أسألك رضاك والجنة وأعوذ بك من سخطك والنار',
    'اللهم آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار. ربنا لا تؤاخذنا إن نسينا أو أخطأنا ربنا ولا تحمل علينا إصرا كما حملته على الذين من قبلنا',
    'اللهم إني أسألك الجنة يا من أقر له بالعبودية كل معبود، يا من يحمده كل محمود، يا من يفزع إليه كل مجهود، يا من يطلب عنده كل مقصود يا من سائله من فضله غير مردود، يا من بابه لسؤاله غير موصود ولا محدود',
    'اللهم بلغنا ما نود، واجعل لنا دعوة لا ترد وافتح لنا بابا إلى الجنة لا يسد',
  ] },
  { id: 'walidayn', n: 'الوالدين والعائلة', i: [
    'رب ارحمهما كما ربياني صغيرا اللهم وفقني لبرهما والإحسان إليهما اللهم ابسط علي وعلى والداي من بركاتك ورحمتك ورزقك، اللهم ألبسهم العافية حتى يهنئا بالمعيشة واختم لهم بالمغفرة حتى لا تضرهم الذنوب، اللهم اكفهم كل هول دون الجنة حتى تبلغهم إياها، برحمتك يا أرحم الراحمين',
    'اللهم يا حافظ النعم احفظ لي من تسعد روحي بقربهم ويطمئن قلبي بهم اللهم إني استودعتك من هم أعز علي من نفسي اللهم احفظ لي من أحب بعينك التي لا تنام',
    'اللهم أسعد عائلتي ومن أحب حتى تبلغ سعادتهم الآخرة، اللهم إني أستعيذك من حزنهم وهمهم وضيقهم ودنيا تخلو منهم',
    'باسمك ربي حصنت نفسي وأهلي ومن أحب من أن يصيبنا أذى، اللهم إني استودعتك أثمن أشيائي وأغلاها، فاحفظها بحفظك يا الله',
    'اللهم عافية في بدن والدي، وطمأنينة في قلبهما، وسعادة في روحهما، وعيشا طويلا في ظلهما، اللهم احفظ لي قرة عيني، ولا تعظم عليهما أمرا، اللهم أطل في عمرهما، وأبعد عنهما كل أذى يا رب العالمين',
    'يا رب عائلتي ومن أحب في ودائعك اللهم ارزقهم لطف القدر وصحة الجسد وطيب الخاطر وعافية الدهر، اللهم احفظهم بعينك التي لا تنام',
    'يا رب إن والداي هم الأحب إلي وخير من أحسن إلي، اللهم احفظهم لي كتفا وسندا وبركة وأمانا',
    'اللهم اغفر لوالدي وارحمهما، وتجاوز عنهما، اللهم اجعلنا من أحب الناس إليهما، ومن أقرب الأبناء لهما، وأكرمنا بحسن السؤال لهما والحرص عليهما، اللهم لا تشغلنا عنهما لا بمال ولا بزوجات ولا بأولاد، اللهم ارزقنا برهما في حياتهما وبعد وفاتهم',
    'اللهم يا ذا الجلال والإكرام يا حي يا قيوم ندعوك باسمك الأعظم الذي إذا دعيت به أجبت، أن تبسط لوالداي من بركاتك ورحمتك ورزقك',
    'اللهم لا تجعل لأمي وأبي ذنبا إلا غفرته، ولا هما إلا فرجته، ولا حاجة من حوائج الدنيا هي لك رضا ولهما فيها صلاح إلا قضيته',
    'اللهم ارزق والداي عيشا قارا، ورزقا دارا، وعملا بارا',
    'اللهم أقر أعين والداي بما يتمنوه في الدنيا، اللهم اجعل أوقاتهما بذكرك معمورة، اللهم أسعدهما بتقواك، اللهم اجعلهما في ضمانك وأمانك وإحسانك',
    'اللهم تقبل توبة والداي وأجب دعوتهما، اللهم إنا نعوذ بك أن تردهما إلى أرذل العمر، اللهم واختم بالحسنات أعمالهما',
    'اللهم إني أدعوك باسمك الواحد الأحد الفرد الصمد، وأدعوك باسمك الأعظم الذي إذا دعيت به أجبت، وإذا سئلت به أعطيت، أن تمنن علي بصلاح أحوال أهلي وذريتي',
    'اللهم حبب لعائلتي الإيمان وزينه في قلوبهم، وكره إليهم الكفر والفسوق والعصيان، واجعلهم من الراشدين، فضلا منك ونعمة وأنت خير الرازقين',
    'اللهم إني أستودعك ذريتي وأهلي يا من لا تضيع عنده الودائع، فاحفظهم وعافهم من كل آفة وعاهة، ومن سوء الأسقام والأمراض، ومن شر طوارق الليل والنهار، ومن شر عين كل حاسد وغل كل حاقد ومن أصدقاء السوء، اللهم احفظهم من بين أيديهم ومن خلفهم وعن أيمانهم وعن شمائلهم ومن فوقهم ومن تحتهم',
    'اللهم ألهم عائلتي في أمرهم الصواب، ويسر لهم في كل مسألة جواب، ونجهم من كل ألوان العذاب، وبيض وجوههم يوم يشتد الحساب، وزين مجلسهم بخير الأصحاب، واجعل دعاءهم دعاء مستجاب',
    'وحاوط عائلتي بسور رحمتك، فلا يقربهم إلا خير يا الله',
  ] },
  { id: 'saada', n: 'السعادة', i: [
    'يا جامع الناس في يوم لا ريب فيه، اجمع بيني وبين سعادتي، توفيقي، ارتياحي، اطمئناني، هداي، وكل أمر يسرني يا الله',
    'ربي استودعتك راحة قلبي وفرحتي ونفسي وأسألك تسهيلا لكل أموري وأستودعك أدعية فاض بها قلبي فاستجبها لي، ويسر لي كل أمر عسير',
    'اللهم لا تعلق قلبي بما ليس لي، واجعل لي نصيبا فيما أحب وارزقني سعادة لا حزن بعدها يا رب',
    'اللهم سعادة القلب وقرة العين وجميل البشائر وسجدة الفرح العميقة',
    'اللهم فتحا مبينا وأنت خير الفاتحين، واجعلني موفقا مسددا مباركا أينما سرت، اللهم افتح لي مغاليق السماوات والأرض وسخر لي المحبة والبركة والجمال وكل من تولى أمري واجعلني خفيفا طيبا أينما نزلت',
    'اللهم بشر قلبي بفرحة تصل للسماء من سعتها وأسعد قلبي بتباشير السعادة والمسرات فإنك على كل شيء قدير',
    'اللهم اجعل ما نريده في حياتنا قريبا لناظرنا سعيدا لخواطرنا',
    'اللهم جبرا لقلبي وروحي، اللهم أرني الفرح في كل ما أريد، يا رب العوض الجميل بعد الصبر الطويل، اللهم دربا لا تضيق به الحياة وقلبا لا يزول منه الأمل، يا رب ازرع في قلبي راحة دائمة وأملا لا يخيب، اللهم ارزقني فرحة تعوض قلبي عن كل ما فات',
    'وأسعدني يا الله بما هو خير لي من أمنياتي ودعواتي، ربي أسعدني حتى أبكي فرحا، يا رب أبعد عني متاعب الدنيا ولا تذقني طعم الحزن ولا دموع الضيق',
    'اللهم اوهبني المتاع والمتعة بالدنيا والآخرة',
    'اللهم غيث من السعادة يسقي الفؤاد فيزهر السعادة والطمأنينة والسلام لقلوبنا أينما حلت',
    'اللهم يا من تملك حوائج السائلين ارزقني وارزق من أحب سرورا لا يشوبه حزن وسعادة لا يعكرها شقاء وعافية لا تزول اللهم بعدد من سجد لك أسعدني وأسعدهم واغفر لي واغفر لهم وفرج همي وهمهم ويسر أمري وأمرهم',
    'اللهم اكتب لي أياما جميلة أسعدني بتفاصيلها واغمرني بخيرك الذي لا يفنى ربي ارزقني حظ الدنيا ونعيم الآخرة',
    'اللهم ارزقني ما أتمنى وأسعدني به. اللهم اغفر لي واعف عني وعافني وارحمني وارزقني وأسعدني',
    'اللهم إن عائلتي هم الرضا وأطهر النعم لقلبي فاسقهم العافية والسعادة بلا منتهى',
    'اللهم اكتب لنا السعادة التي لا شقاء بعدها أبدا. اللهم لك أسلمت وبك آمنت وعليك توكلت وبك خاصمت وإليك حاكمت، فاغفر لي ما قدمت وما أخرت، وما أسررت وما أعلنت، وأنت المقدم وأنت المؤخر لا إله إلا أنت، أنت الأول والآخر والظاهر والباطن عليك توكلت وأنت رب العرش العظيم',
  ] },
  { id: 'thabat', n: 'ثبات الدين', i: [
    'يا مقلب القلوب: ثبت قلبي على حبك وعلى تقواك وخشيتك',
    'اللهم ثباتا لا يحول، وهدى لا يزيغ',
    'اللهم إن حال قلبي إلى غيرك.. فرده إليك ردا جميلا',
    'اللهم أستودعك قلبي وإيماني، وحيائي منك',
    'اللهم اجعلنا من جندك فإن جندك هم الغالبون، واجعلنا من حزبك فإن حزبك هم المفلحون، واجعلنا من أوليائك فإن أولياءك لا خوف عليهم ولا هم يحزنون',
    'اللهم أعني على ما ينجيني مما خوفتني منه وارزقني شوق الصالحين إلى ما شوقتهم إليه',
    'اللهم اهدنا لما اختلف فيه من الحق بإذنك إنك تهدي من تشاء إلى صراط مستقيم',
    'اللهم اشغل قلوبنا بحبك، وألسنتنا بذكرك، وأبداننا بطاعتك وعقولنا بالتفكر في خلقك والتفقه في دينك',
    'اللهم رب جبرائيل وميكائيل وإسرافيل فاطر السماوات والأرض عالم الغيب والشهادة أنت تحكم بين عبادك فيما كانوا فيه يختلفون اهدني لما اختلف فيه من الحق بإذنك إنك تهدي من تشاء إلى صراط مستقيم',
    'اللهم توفيقا يبقيني على صراطك المستقيم',
    'اللهم اجعلني أراك في كل الأمور وثبتني على الطاعة',
    'اللهم لا تجعل للشيطان علي سبيلا',
    'اللهم إيمانا لا يرتد اللهم اجعل قلبي ساعيا إليك، باحثا عنك، غنيا بك عن العالمين',
    'نسألك اللهم من خفي ألطافك، لطفا تهدي به قلوبنا فتفرح بالحق وتحبه وتألفه وترضاه وتثبت عليه، ولطفا تصرف به عنا ما يؤذينا أو يضرنا، ولطفا تدفع به عنا البلاء والفتن',
    'اللهم يا حبيب التائبين، ويا سرور العابدين، ويا قرة أعين العارفين، ويا أنيس المنفردين، ويا حرز اللاجئين، ويا ظهير المنقطعين، ويا من حنت إليه قلوب الصديقين، اجعلنا من أوليائك المقربين، وحزبك المفلحين. وأدم علينا قربك',
    'إلهي حبب إلي طاعتك، فلا أعود أتكلفها وإنما أقبل عليها إقبال المريد المحب المشتاق.. فتصبح عندي لذة لا عبئا ولا واجبا وحياة متجددة لا عادة جامدة',
    'اللهم يا مقلب القلوب والأبصار، ثبت قلوبنا على طاعتك، ولا تزغ قلوبنا بعد إذ هديتنا، ولا تفتنا في ديننا، واجعل يومنا خيرا من أمسنا، واجعل غدنا خيرا من يومنا، واجعل خير أعمارنا أواخرها، وخير أعمالنا خواتيمها، وخير أيامنا يوم نلقاك وأنت راض عنا',
    'اللهم أحيني على سنة نبيك محمد صلى الله عليه وسلم وتوفني على ملته وأعذني من مضلات الفتن',
    'اللهم إني أعوذ بك من يوم السوء ومن ليلة السوء ومن ساعة السوء ومن صاحب السوء ومن كل سوء في الدنيا والآخرة',
    'يا نور السماوات والأرض، يا أحد يا صمد يا فرد، هب لنا فرقانا يعصمنا، هب لنا نورا يهدينا، نعوذ بك من نقمة السوء وظن السوء، نعوذ بك من تيه الغرور وغل الصدور، رب اجعل لذة معرفتك تستغرق طاقة قلوبنا، واجعل نور معيتك يسدد بصائرنا، احفظنا، أحبنا، وارض عنا يا أكرم الأكرمين، نسألك بركتك وعطفك ولطفك وعافيتك وبرك ورحمتك وحبك، نعوذ بك من تقلبات القلوب والأيام، اعصمنا من المعاصي والآثام، اشغلنا بخير ما يرضيك عنا، احمنا من أذى الناس، اشغلنا بك عن همومنا، اجعل الآخرة كل همنا',
    'يا من تزيد في الخلق ما تشاء زدنا قوة منك نتقوى بها على طاعتك نلتمس عونا منك لنقوم بشكر نعمك أطفئ لوعة قلوبنا بفيض من حبك ولطفك',
    'اللهم إني أسألك الرضا بالقضاء والقدر وبرد العيش بعد الموت ولذة النظر إلى وجهك والشوق إلى لقائك في غير ضراء مضرة ولا فتنة مضلة',
    'اللهم اجعل حبك أحب الأشياء إلي، واجعل خشيتك أخوف الأشياء عندي، واقطع عني حاجات الدنيا بالشوق إلى لقائك، وإذا أقررت أعين أهل الدنيا من دنياهم، فأقرر عيني من عبادتك',
    'اللهم فرغني لما خلقتني له، ولا تشغلني بما قد تكفلت لي به، ولا تحرمني وأنا أسألك، ولا تعذبني وأنا أستغفرك. يا عظيم العفو، يا واسع المغفرة، يا قريب الرحمة، يا ذا الجلال والإكرام، هب لي العافية في الدنيا والآخرة',
    'اللهم اجعل الدين بصري وبصيرتي، وثبتني على الصواب',
  ] },
  { id: 'hubb', n: 'حُبّ الله', i: [
    'اللهم ارزقني حبك، وحب من ينفعني حبه عندك، اللهم ما رزقتني مما أحب فاجعله قوة لي فيما تحب اللهم حبا، تكون فيه سمعي وبصري وخطاي',
    'اللهم حبك، اللهم قربك، اللهم نورك، حتى نلقاك اللهم عظم حبك في قلبي اللهم لا أسألك إلا أنت',
    'اللهم حبك، وصنع عيينك يا رب، أحبك وأخافك فأحبني وآمني أسألك حبك، والحب فيك، والحب لك، والحب منك، وحب من يحبك، وحب من تحب، وحب ما تحب، وحب ما يقربني إلى ما تحب',
    'وأعوذ بك من حب لا يبدأ بك اللهم املأ قلبي بك؛ فلا يرى غيرك',
    'اللهم ما زويت عني مما أحب فاجعله لي قوة فيما تحب',
    'يا رب ارزقنا حبك وبارك لنا فيه واجعلنا أهلا له',
    'اللهم علمنا الحب وآمنا في الحب وسيرنا في دروبنا حبا لك',
    'اللهم ثبت قلبي بحبك وطاعتي إيمانا بك ورجائي في لقاك فإنه لا إله إلا أنت',
    'اللهم أكرمني بحبك ورحمتك وعطائك واسقني لطفك ورأفتك',
    'اللهم لا أسأل حبا إلا حبك',
    'اللهم اجعل قلبي مملوءا بك وبحبك وبحب فعل الخير قربا إليك',
    'اللهم حببني إليك وإلى ملائكتك وأنبيائك ورسلك وعبادك الصالحين، واجعلني ممن يحبك ويحب ملائكتك وأنبياءك ورسلك وعبادك الصالحين',
    'اللهم أحي قلبي بحبك واجعلني لك كما تحب، اللهم اجعلني أحبك بقلبي كله وأرضيك بجهدي كله، اللهم اجعل حبي كله لك، وسعيي كله في مرضاتك',
    'اللهم إليك مددت يدي، وفيما عندك عظمت رغبتي فأحبني واجعل لي من كل خير نصيبا، وإلى كل خير سبيلا برحمتك يا أرحم الراحمين',
    'اللهم قربني لك حبا وردني إليك حبا',
  ] },
  { id: 'hajat', n: 'قضاء الحاجات', i: [
    'وأعوذ بك اللهم من درب مسدود، وسعي مردود، وظن مخذول وأن يتعلق قلبي بما ليس لي',
    'اللهم ألهمني حجتي وقت حاجتي',
    'اللهم مالك الملك تؤتي الملك من تشاء، وتنزع الملك ممن تشاء، وتعز من تشاء، وتذل من تشاء، بيدك الخير إنك على كل شيء قدير، رحمن الدنيا والآخرة ورحيمهما، تعطيهما من تشاء، وتمنع منهما من تشاء، ارحمني رحمة تغنيني بها عن رحمة من سواك',
    'لا إله إلا الله، الحليم الكريم، سبحان الله رب العرش العظيم، الحمد لله رب العالمين، أسألك موجبات رحمتك، وعزائم مغفرتك والغنيمة من كل بر والسلامة من كل إثم، اللهم لا تدع لي ذنبا إلا غفرته، ولا هما إلا فرجته ولا حاجة هي لك رضا إلا قضيتها يا أرحم الراحمين',
    'اللهم إني ضيفك وأنت أكرم الأكرمين فبلغني كل ما أريد فليس ذلك عليك بعزيز',
    'يا رب نتوسل إليك أن تقول لأمنياتنا وأحلامنا ودعائنا كوني اللهم استجب دعاءنا وحقق آمالنا ورجاءنا وأمنياتنا وانصرنا على من ظلمنا وعادانا اللهم آمين يا رب العالمين',
    'اللهم يا مسهل الشديد ويا ملين الحديد ويا منجز الوعيد ويا من هو كل يوم في أمر جديد أخرجني من حلق المضيق.. إلى سعة الطريق بك أدفع ما لا أطيق ولا حول ولا قوة إلا بالله العلي العظيم',
    'اللهم يا سميع يا بصير يا من هو على كل شيء قدير يا من كان نعم المجيب لنوح لما دعاه يا ذا الجلال اللهم حقق أمنياتى وبارك اللهم فيها، يا مسبب الأسباب يا مفتح الأبواب يا مجيب الدعوات يا قابل الحاجات يا سامع الأصوات',
    'اللهم بحقك يا كريم وبحمدك يا محمد حقق يا رب حلمي وظني فيك يا رب جميل فحقق يا إلهي حسن ظني يا رب حقق لنا كل ما تتمناه قلوبنا عاجلا غير آجل برحمتك وقدرتك على كل شيء يا أرحم الراحمين يا أكرم الأكرمين يا رب العالمين إنك على كل شيء قدير يا رب إنك تقول للشيء كن فيكون',
    'اللهم بحق العرش ومن علاه، وبحق الوحي ومن أوحاه، وبحق النبي ومن نبأه، وبحق البيت ومن بناه، ويا سامع كل صوت، يا جامع كل فوت، ويا بارئ النفوس بعد الموت، آتني فرجا من عندك بشهادة أن لا إله إلا الله وأن محمدا عبدك ورسولك',
    'اللهم لا تجعل لنا أملا إلا بك اللهم حقق لنا جميعا ما نتمنى لا إله إلا أنت سبحانك إني كنت من الظالمين أستغفر الله الذي لا إله إلا هو الحي القيوم وأتوب إليه. اللهم حقق لي ما أريد في هذه الحياة فأنت تعلم ما أريد وما أسعى إليه. اللهم صلني إلى الطريق الصحيح حتى أصبح ذا شأن عظيم في هذه الحياة اللهم وفقني لما تحب وترضى',
    'يا مقيل العثرات، يا قاضى الحاجات اقض حاجتى، وفرج كربتى، وارزقنى من حيث لا أحتسب',
  ] },
  { id: 'afiya', n: 'الصحة والعافية', i: [
    'اللهم عافني في بدني، اللهم عافني في سمعي، اللهم عافني في بصري، لا إله إلا أنت اللهم أمتعني بسمعي وبصري حتى تجعلهما الوارث مني، وعافني في ديني وفي جسدي، وانصرني ممن ظلمني حتى تريني فيه ثأري اللهم إني أسلمت نفسي إليك، وفوضت أمري إليك، وألجأت ظهري إليك، ووجهت وجهي إليك، لا ملجأ ولا منجى منك إلا إليك، آمنت برسولك الذي أرسلت، وبكتابك الذي أنزلت',
    'اللهم إني أسألك العافية في الدنيا والآخرة اللهم إني أسألك العفو والعافية في ديني ودنياي وأهلي ومالي اللهم استر عوراتي وآمن روعاتي اللهم احفظني من بين يدي ومن خلفي وعن يميني وعن شمالي ومن فوقي وأعوذ بعظمتك أن أغتال من تحتي',
    'اللهم إنا نسألك المعافاة في الدنيا والآخرة',
    'اللهم ألبسني ثوب الصحة والعافية على الدوام يا أرحم الراحمين',
    'يا إلهي، اسمك شفائي، وذكرك دوائي، وقربك رجائي، وحبك مؤنسي، ورحمتك طبيبي ومعيني في الدنيا والآخرة، وإنك أنت المعطي العليم الحكيم',
    'اللهم إنا نسألك تمام العافية، ونسألك دوام العافية، ونسألك الشكر على العافية، ونسألك الغنى عن الناس، اللهم عافنا في أبداننا، اللهم عافنا في أسماعنا، اللهم عافنا في أبصارنا اللهم إنا نسألك العفو والعافية في الدين والدنيا والآخرة',
    'اللهم أنت الميسر وأنت المسهل سهل أمري وحقق مطلبي اللهم لا تبتلني بمن أحب بعدا ولا فقدا ولا حزنا ولا مرضا اللهم إني أعوذ بك من عين تصيب القلب فتحزنه والرزق فتنقصه، والبال فتتعبه والنجاح فتفشله اللهم أخرجني من أشد الضيق إلى أوسع الفرج',
    'اللهم يا رب، اشف مرضى المسلمين وعافهم، وخفف عنهم ألمهم وألم كل مريض، وارحم موتانا، واشف شفاء لا يغادر سقما، واشف مؤمنين المرضى ومؤمنين الأحياء، وحمدا لله على كل حال',
    'اللهم إني أعوذ بك من زوال نعمتك، وتحول عافيتك، وفجاءة نقمتك، وجميع سخطك',
    'اللهم وشافنا وعافنا واعف عنا، واشملنا بعطفك ومغفرتك، وتولنا برحمتك يا أرحم الراحمين',
    'اللهم اجعل الصحة خير صاحب لأجسادنا والسعادة خير رفيق لقلوبنا والفرحة خير نور لعيوننا، والتوفيق الدائم في دروبنا، إنك على كل شيء قدير',
    'اللهم إنا نسألك بنور وجهك الذي أشرقت له السموات والأرض أن تجعلنا في حرزك وحفظك وجوارك وتحت كنفك، اللهم ألبسنا لباس الصحة والعافية وارزقنا من واسع رزقك وتقبل أعمالنا بقبول حسن يا رب العالمين',
  ] },
  { id: 'hazz', n: 'الحظ', i: [
    'يا رب حقق لي ما أريد فأنت تعلم السر وما يخفى، إني تمنيت الكثير وكل الكثير بيدك، يا رب شيء يغير كل شيء، اللهم أسعدني سعادة لا يعقبها حزن سخر لي من حظوظ الدنيا أطيبها، ربي اصرف عني ما يقلقني وأرح قلبي برحمتك يا الله',
    'اللهم النصيب الجميل من كل شيء، اللهم ما بالقلب وطال الدعاء به، اللهم جبرا واستجابة ومغفرة ومرضاة، وإنك لسميع الدعاء',
    'يا رب سخر لي حظا ونصيبا يتعجب منه أهل السماوات والأرض، تسخير ونصيب يليق بجلالك وقدرتك وكرمك يا أرحم وأكرم الأكرمين',
    'اللهم يا رب المعجزات ويا رب المستحيلات أرني عجائب قدرتك في تحقيق ما أطلب وما أتمنى',
    'واجعلني ذا حظ عظيم يا كريم يا جواد',
    'اللهم اجعل لنا نصيبا في سعة الأرزاق وتيسير الأحوال وقضاء الحاجات وإجابة الدعوات',
    'الله سبحانك وتعاليت منك اليقين وإليك أتوسل بكل قدرتك أن ترزقني الحظ الجيد وأن تمنحني توفيقا في حياتي منقطع النظير اللهم آمين',
    'ارزقني يا الله الحظ الجميل وارفع من درجتي في الدنيا وفي الآخرة اللهم آمين واقبل مني أعمالي الصالحة وأدخلني الجنة يا كريم',
    'اللهم رب جبرائيل وميكائيل وإسرافيل فاطر السموات والأرض عالم الغيب والشهادة أنت تحكم بين عبادك فيما كانوا فيه يختلفون اهدني إلى ما اختلف فيه من الحق اللهم غيرني وغير حالي وقدري للأفضل يا رب رزق لم أتوقعه وخير لم أفكر به وتحقيق أمنيات ظننت أنها مستحيلة',
    'اللهم افتح لي الأبواب ويسر لي الأمور واجعل لي القبول اللهم إنك تعلم أني عبد وأنت رب فجد علي بما عندك يا ربي بما تجود به على عبدك اجعل في لساني قولا ثوابا وفي قلبي إخلاصا وتوفيقا اللهم افتح لي مغاليق الأمور',
    'اللهم زدنا ولا تنقصنا وأكرمنا ولا تهنا وأعطنا ولا تحرمنا وآثرنا ولا تؤثر علينا وأرضنا وارض عنا',
    'اللهم إني أسألك الحظ العظيم الجميل وأسألك القبول بين الخلق وأن تسخر لي الأرض وما عليها وكل من وليته أمري',
    'اللهم ما قسمت في هذه الحياة من خير وصحة وسعة رزق فاجعل لنا منه أوفر الحظ والنصيب',
  ] },
  { id: 'maghfira', n: 'المغفرة والتوبة', i: [
    'أسألك بحبي لك: أن تغفر لي. أسألك بخوفي منك: أن تغفر لي. أسألك برجائي فيك: أن تغفر لي',
    'اللهم كنفك وظلك، واستغراق رأفتك واشتمال تجاوزك',
    'يا من أظهر الجميل وستر القبيح يا من لا يؤاخذ بالجريرة ولا يهتك الستر يا عظيم العفو يا حسن التجاوز يا واسع المغفرة يا باسط اليدين بالرحمة يا صاحب كل نجوى ويا منتهي كل شكوى يا كريم الصفح يا عظيم المن يا مبتدئ النعم قبل استحقاقها يا ربنا ويا مولانا ويا غاية رغبتنا أسألك يا الله ألا تشوي خلقي بالنار',
    'اللهم أنت الجميل في ولايتك والجميل في فضلك والجميل في رحمتك! جملنا بعفوك وهدايا كرمك ونفحات عتقك، وكن لنا ولا تكن علينا، أنت الرحمن الرحيم، سبحانك وبحمدك',
    'اللهم إني أسألك باسمك الطاهر الطيب المبارك الأحب إليك الذي إذا دعيت به أجبت وإذا سئلت به أعطيت وإذا استرحمت به رحمت وإذا استفرجت به فرجت، اللهم إني أدعوك الله وأدعوك الرحمن وأدعوك البر الرحيم، وأدعوك بأسمائك الحسنى كلها ما علمت منها وما لم أعلم أن تغفر لي وترحمني',
    'يا كريم العفو.. يا حسن التجاوز اغفر لنا واعف عنا',
    'ربنا لا تؤاخذنا إن نسينا أو أخطأنا، ربنا ولا تحمل علينا إصرا كما حملته على الذين من قبلنا',
    'ربنا ولا تحملنا ما لا طاقة لنا به واعف عنا واغفر لنا وارحمنا أنت مولانا فانصرنا على القوم الكافرين',
    'اللهم إن ذنوبي عظام وهي صغار في جنب عفوك يا كريم، فاغفرها لي',
    'اللهم إنا قد أطعناك في أحب الأشياء إليك أن تطاع فيه، الإيمان بك، والإقرار بك، ولم نعصك في أبغض الأشياء أن تعصى فيه؛ الكفر والجحد بك، اللهم فاغفر لنا ما بينهما',
    'اللهم يا بارئ البريات، وغافر الخطيات، وعالم الخفيات، المطلع على الضمائر والنيات، يا من أحاط بكل شيء علما، ووسع كل شيء رحمة، وقهر كل مخلوق عزة وحكما، اغفر لي ذنوبي، واستر عيوبي، وتجاوز عن سيئاتي إنك أنت الغفور الرحيم',
    'اللهم اغفر لي جميع ما مضى من ذنبي واعصمني فيما بقي من عمري وارزقني عملا زاكيا ترضى به عني',
  ] },
  { id: 'hidaya', n: 'الصلاح والهداية', i: [
    'اهدنا الصراط المستقيم',
    'اللهم اهدنا فيمن هديت، وتولنا فيمن توليت',
    'يا رب: أسألك قربا لا يحجب، ووصلا لا ينقطع، ونورا لا يأفل اللهم زدني قربا منك، واشرح صدري لكل ما تحب ويرضيك يا واصل المنقطعين، أوصلني بك، وأوصلني إليك، واجعلني على صراطك المستقيم، حتى ألقاك',
    'اللهم لذة الأنس بك اللهم بنور وجهك الجميل، انظر إلي بعين الرحمة والرضا اللهم أقر في قلبي ما وقر في قلب أبي بكر اللهم حبب إلينا الإيمان وزينه في قلوبنا اللهم حياة كما تحب وترضى',
    'اللهم أبعدني عما يبعدني عنك اللهم سعيا يرضيك، وسيرا تحبه',
    'اللهم خذ بيدي إليك، وخذ بيدي عند كل أمر، اللهم لا علم لي إلا ما علمتني ولا قوة لي إلا بما أعنتني',
    'إلهي، وخالقي، وولي: أسألك المعية في الدنيا والآخرة، اللهم صلني بك، فلا أضل ولا أشقى',
    'اللهم اجعلنا من عبادك الصالحين.. الذين يرثون الفردوس وهم فيها خالدون.. ومن الذين يؤتون ما آتوا وقلوبهم وجلة أنهم إلى ربهم راجعون.. واجعلنا من الذين يسارعون في الخيرات وهم لها سابقون',
    'اللهم اجبر خواطرنا بوسعك.. ولا تقطع رجاءنا فيك بمنعك.. فإنا لا طاقة لنا في البعد عنك.. ولا نجاة لنا إلا في كل سبيل يؤدي إليك',
    'لا تقبض روحي إلا وأنا على حال تحبه، يا الله',
    'يا رب وفرة النور، وبركة الفكرة، وزوال المآثم، وبهجة المبسم، فيض السواقي، وصلاح الحواس، وظلال الرحمة',
    'يا رب وألا يغيب عني نورك',
  ] },
  { id: 'tawakkul', n: 'التوكل', i: [
    'اللهم إني متوكل عليك، واثق بوعدك راض بصنعك محسن الظن بك ومنتظر فرجك فأنت حسبي ونعم الوكيل فوضت أمري إليك وتوكلت عليك فيا رب اغفر لي وارحمني واهدني واجبرني وعافني وارزقني وارفعني وتولني فيمن توليت وهب لي يا كريم من كل خير خزائنه بيدك واصرف عني كل شر وارحمني رحمة تغنيني عمن سواك',
    'اللهم إني أبرأ من حولي وقوتي وألجأ لحولك وقوتك، اللهم أعني لنيل رضاك، اللهم أعني على كل عمل يقربني إليك',
    'تركتها لك يا الله ووكلت أمري إليك فبشرني بما أريد وبما اخترته لي خير',
    'يا مهيئ الظروف وخالق المسببات الملهم الممكن، لك أموري كلها فمكنها',
    'يا رب سهل لي دروب الخير في كل اتجاه فوضت لك يا خالقي أدق الأمور وأجلها',
    'بسم الله، توكلت على الله، لا حول ولا قوة إلا بالله',
    'وكلت على الحي الذي لا يموت، توكلت على من بيده نواصي العباد، توكلت على الحي الذي لا يعجل، توكلت على المعبود الذي لا يجور، توكلت على الصمد الذي لم يلد ولم يولد، توكلت على القادر القاهر العلي الصمد',
    'اللهم بك أستعين وعليك أتوكل، اللهم ذلل لي صعوبة أمري وسهل لي مشقته، وارزقني من الخير كله أكثر مما أطلب واصرف عني كل شر',
    'اللهم إني أسألك صدق التوكل عليك وحسن الظن بك',
    'اللهم أنت ربي لا إله إلا أنت عليك توكلت وأنت رب العرش العظيم، ما شاء الله كان وما لم يشأ لم يكن لا حول ولا قوة إلا بالله العلي العظيم، أعلم أن الله على كل شيء قدير، وأن الله قد أحاط بكل شيء علما، اللهم إني أعوذ بك من شر نفسي ومن شر كل دابة أنت آخذ بناصيتها إن ربي على صراط مستقيم',
    'توكلت على الله الذي لا يغلبه أحد، توكلت على الجبار الذي لا يقهره أحد، توكلت على العزيز الرحيم',
    'اللهم اجعلني ممن توكل عليك فكفيته، واستهداك فهديته، واستنصرك فنصرته',
  ] },
  { id: 'khatima', n: 'حُسن الخاتمة', i: [
    'أسألك بنور وجهك أن تنير قبري يوم لا نور إلا نورك، أن تؤمن روعتي ووحشتي، يوم لا أمان إلا بك وأسألك حسن الختام اللهم ارحمنا إذا عرق منا الجبين، وكثر الأنين، وأيس منا الطبيب، وبكى علينا الحبيب',
    'اللهم أعنا على الموت وكربته، وعلى القبر وغمته، وعلى الميزان وخفته، وعلى الصراط وزلته، ويوم القيامة وروعته',
    'اللهم لا تقبض روحي إلا وأنت راض عني اللهم ثبتني عند السؤال اللهم اجعل قبري روضة من رياض الجنة وأشهد أني أحسن الظن بك ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار',
    'رب أنت وليي في الدنيا والآخرة توفني مسلما وألحقني بالصالحين',
    'اللهم إني أسألك عيشة نقية، وميتة سوية، ومردا غير مخز ولا فاضح',
    'اللهم اختم بالصالحات أعمالنا، وبالسعادة آجالنا، وبلغنا مما يرضيك آمالنا',
    'اللهم أصلح لي ديني الذي هو عصمة أمري، وأصلح لي دنياي التي فيها معاشي، وأصلح لي آخرتي التي فيها معادي، واجعل الحياة زيادة لي في كل خير، واجعل الموت راحة لي من كل شر',
    'اللهم أنت خلقت نفسي، وأنت توفاها، لك مماتها ومحياها، وإن أحييتها فاحفظها، وإن أمتها فاغفر لها، اللهم إني أسألك العافية',
  ] },
  { id: 'khuluq', n: 'حُسن الخُلُق', i: [
    'اللهم اهدني لأحسن الأخلاق، لا يهدي لأحسنها إلا أنت، واصرف عني سيئها، لا يصرف عني سيئها إلا أنت',
    'اللهم جنبني منكرات الأخلاق والأهواء، والأعمال والأدواء',
    'اللهم كما حسنت خلقي فحسن خلقي',
    'اللهم إني أسألك الهدى، والتقى، والعفاف، والغنى',
    'اللهم حسن الخلق في الغضب والرضا اللهم اجعلني ممن تقضى حوائج الناس على يديه',
    'اللهم إني أسألك حسن الأخلاق، وحسن الأفعال، وحسن ردود الأفعال اللهم زكني هذبني علمني زدني حبا وبركة ورحمة ولطفا وزكاة من زكاتك، زدني يقينا بتدابيرك يقينا يغنيني عن الخوف من كل شيء سواك. اللهم حرر حركاتنا وسكناتنا عن إرادات سوانا',
    'اللهم إني أعوذ بك من منكرات الأخلاق والأعمال والأهواء',
    'يا الله كرهني بكل عمل يعصيك، واهدني لفعل ما يرضيك عني',
    'اللهم آت نفوسنا تقواها وزكها أنت خير من زكاها، أنت وليها ومولاها',
    'اللهم اجعلني مفتاحا للخير مغلاقا للشر ولا تجعلني مفتاحا للشر مغلاقا للخير',
    'اللهم إني أسألك صحة في إيمان، وإيمانا في حسن خلق، ونجاحا يتبعه فلاح، ورحمة منك وعافية، ومغفرة منك ورضوانا',
    'اللهم سماحة الأخلاق ولين القلب وحكمة العقل وجمال الروح وفصاحة اللسان وبشاشة الوجه',
    'اللهم عقلا حكيما ونفسا صبورة، اللهم اجعل بسمتي عادة وحديثي عبادة وحياتي سعادة وخاتمتي شهادة',
    'اللهم اهدني لأحسن الأعمال، وأحسن الأخلاق، لا يهدي لأحسنها إلا أنت، وقني سيئ الأعمال، وسيئ الأخلاق، لا يقي سيئها إلا أنت',
    'اللهم ألف بين قلوبنا، وأصلح ذات بيننا',
  ] },
  { id: 'faraj', n: 'الفرج', i: [
    'اللهم لا بأس، ولا يأس، ولا انطفاء',
    'اللهم لا تعذبنا بمرض ولا تشقنا بولد ولا تسلط علينا أحدا ونجنا من شر النفاثات في العقد ومن شر حاسد إذا حسد ومن حاقد إذا حقد واجعل لنا من كل هم فرجا من كل ضيق مخرجا ومن كل داء دواء ومن كل مرض شفاء ومن كل بلاء عافية وارحم اللهم موتانا واشف مرضانا يا رب العالمين',
    'اللهم إنك النجاة فأنجني، وإن أويت بكل ذبول أرهقني فقوني، وإن أصبحت بروح باهتة فأنر لي قلبي يا رب',
    'اللهم وإن استحالت أحسنها بلطفك',
    'يا رب من نام فينا على ضيق فأيقظه على فرج، ومن نام على حزن فأيقظه على فرح، ومن نام على عسر فأيقظه على يسر، اللهم أخرج من أجسامنا كل مرض وكل سم وكل سحر وكل عين وكل حزن وكل هم وكل غم وكل ضيق وأبدله بالصحة والسعادة والفرج مدي حياتنا',
    'ولا تحملنا ما يرخي قوة أكتافنا يا رحيم',
    'يا رب يا حي يا قيوم يا أحد يا صمد يا منان يا بديع السموات والأرض يا حي يا قيوم يا ذا الجلال والإكرام، يا ودود يا ودود يا رب العرش العظيم يا فعالا لما تريد أسألك بعزك الذي لا يضام وملكك الذي لا يرام ونورك الذي ملأ أركان عرشك اللهم أغثني اللهم أغثني',
    'اللهم إني أنشدك عهدك ووعدك',
    'يا رب، أدعوك بعزتك وجلالك، أن لا تصعب لي حاجة، ولا تعظم علي أمرا، ولا تحن لي قامة، ولا تفضح لي سرا، ولا تكسر لي ظهرا',
    'اللهم أزح من قلبي كل خوف يسكنني، وكل ضعف يكسرني، وكل أمر يبكيني، وافتح لي أبوابي المغلقة',
    'اللهم إني أعوذ بك من جهد البلاء، ودرك الشقاء، وسوء القضاء، وشماتة الأعداء',
    'يا فارج الهم ويا كاشف الغم فرج همي ويسر أمري، وارحم ضعفي وقلة حيلتي، وارزقني من حيث لا أحتسب يا رب العالمين',
    'اللهم أبدل حزني فرحا، وهمومي سعادة، وضيقي فرجا',
  ] },
  { id: 'tumanina', n: 'الطمأنينة والأمان', i: [
    'يا رب السكون؛ ورب السكينة /يا رب الأمان، ورب الطمأنينة: أسألك سعيا مطمئنا',
    'اللهم الاطمئنان بك، وحسن التوكل عليك، وصدق السعي إليك',
    'اللهم ارزقنا سكينة منك تشرح بها صدورنا.. ونظرة رضا منك تكشف بها كروبنا.. وسيرة طيبة بين خلقك ترفع بها قدرنا',
    'لا تبتلنا يا الله بما نخاف منه.. ولا تمتحنا بما نخاف عليه.. وارزقنا السكينة والطمأنينة والسلامة والعافية',
    'أسألك يا الله ألا تغلق رحاب صدري أبدا',
    'اجعل في نفسي نورا، وأعظم لي نورا',
    'أسألك سكونا لا وحشة فيه',
    'اللهم دبر ما نجهله، ويسر ما نأمله، وقرب ما نرقبه، وهب لنا نورا يملؤنا.. وتولنا يا رب فيمن توليت',
    'اللهم إني أسألك نفسا مطمئنة، تؤمن بلقائك، وترضى بقضائك، وتقنع بعطائك',
    'هبني سكينة من عندك يا رب أقاوم بها قلقي، هبني طمأنينة أوازن بها روحي، هبني من الحكمة ما أقوم به اعوجاجي ومن فضلك ما يغمرني وينور بصيرتي يا رب',
    'حسبي أنك ربي ولا يخفي عليك ما في قلبي، فاللهم طمأنينة منك وغنى بك',
    'اللهم اجعل بالي مشغولا بك عن غيرك، اللهم اصنعني على عينك، اللهم لا تدع في صدري ما يهمني ويقلقني فإنك على كل شيء قدير',
    'رب إني أسألك أن تريح قلبي وفكري وأن تصرف عني شتات العقل والتفكير',
    'اللهم لا تحرمنا سعة رحمتك، وسبوغ نعمتك، وشمول عافيتك، وجزيل عطائك، ولا تمنع عني هباتك لسوء ما عندي، ولا تجازني بقبيح عملي، ولا تصرف وجهك الكريم عني برحمتك يا أرحم الراحمين',
    'اللهم إني أسألك الصبر عند القضاء، ومنازل الشهداء، وعيش السعداء، والنصر على الأعداء، ومرافقة الأنبياء، يا رب العالمين',
    'اللهم ارض عني واسلل سخيمة قلبي، اللهم قربني إليك، واجعلني من أهلك وخاصتك، اللهم اجعل بالي مرتاحا، وقلبي مطمئنا يا رحمن يا رحيم',
    'اللهم إني أسألك بالا مرتاحا، وقلبا خاشعا، ولسانا عامرا بذكرك، اللهم إنك من تكن معه فقد فاز ونجى، اللهم كن معي',
  ] },
  { id: 'qurb', n: 'القرب من الله', i: [
    'يا رب: أسألك قربا لا يحجب، ووصلا لا ينقطع، ونورا لا يأفل',
    'اللهم زدني قربا منك، واشرح صدري لكل ما تحب ويرضيك',
    'يا واصل المنقطعين، أوصلني بك، وأوصلني إليك، واجعلني على صراطك المستقيم حتى ألقاك',
    'اللهم لذة الأنس بك',
    'إلهي، وخالقي، ووليي: أسألك المعية في الدنيا والآخرة، اللهم صلني بك، فلا أضل ولا أشقى',
    'اللهم اجبر خواطرنا بوسعك.. ولا تقطع رجاءنا فيك بمنعك.. فإنا لا طاقة لنا في البعد عنك.. ولا نجاة لنا إلا في كل سبيل يؤدي إليك',
    'اللهم خذ بيدي إليك، وخذ بيدي عند كل أمر، اللهم لا علم لي إلا ما علمتني، ولا قوة لي إلا بما أعنتني',
    'اللهم سعيا يرضيك، وسيرا تحبه',
    'اللهم اجعلنا من عبادك الصالحين.. الذين يرثون الفردوس وهم فيها خالدون.. ومن الذين يؤتون ما آتوا وقلوبهم وجلة أنهم إلى ربهم راجعون.. واجعلنا من الذين يسارعون في الخيرات وهم لها سابقون',
    'إلهي.. لا تحجب سؤالي ولا تتركني لنفسي',
    'يا رب وفرة النور، وبركة الفكرة، وزوال المآثم، وبهجة المبسم، فيض السواقي، وصلاح الحواس، وظلال الرحمة',
    'اللهم إني أسألك في صلاتي ودعائي بركة تطهر بها قلبي، وتكشف بها كربي، وتغفر بها ذنبي، وتصلح بها أمري، وتغني بها فقري، وتذهب بها شري، وتكشف بها همي وغمي، وتشفي بها سقمي، وتقضي بها ديني، وتجلو بها حزني، وتجمع بها شملي، وتبيض بها وجهي',
    'اللهم إليك مددت يدي، وفيما عندك عظمت رغبتي، فاقبل توبتي، وارحم ضعف قوتي، واغفر خطيئتي، واقبل معذرتي، واجعل لي من كل خير نصيبا، وإلى كل خير سبيلا برحمتك يا أرحم الراحمين',
    'اللهم إني أسألك توفيقا في طريقي، وراحة في نفسي، وتيسيرا في أمري، رب أعوذ بك من شتات الأمر، ومس الضر، وضيق الصدر',
    'اللهم قرب قلبي إليك، وزده قربا منك اللهم إني أسألك أن تدلني عليك وألا تقطعني عنك، حتى أجد في قربك أنس الدنيا وسعادة الآخرة',
  ] },
  { id: 'rida', n: 'الرضا', i: [
    'وأسألك الرضا بعد القضاء',
    'رضيت بالله ربا، وبالإسلام دينا، وبمحمد صلى الله عليه وسلم نبيا',
    'اللهم إني أسألك نفسا مطمئنة تؤمن بلقائك، وترضى بقضائك، وتقنع بعطائك أشهد أني راضية عن كل أقدارك؛ وأشهد أنك العدل',
    'أسألك بحبي وشوقي، أسألك بخوفي وهلعي، أسألك برجائي وأملي، أن ترضى عني وترحمني اللهم إني أسألك عينا راضية، ونفسا مطمئنة اللهم سكن نفوسنا بالرضا لما قضيت.. والتسليم لما حكمت',
    'اللهم علمنا الرضا، وبصرنا بالرضا، وشدنا بالرضا، واسكب في قلوبنا الرضا',
    'اللهم إني أسألك الرحمة، ورضا عينيك اللهم اجعلنا أرضى الناس بقضائك وقدرك وأسعد الناس بلطفك وعافيتك وحبك وأنسك ورضاك اجعلنا محل كرامتك وحنانك وبرك وامتنانك اشملنا بسترك اغمرنا بنور من فيض صنائع عطاياك',
    'اللهم إني أسألك إيمانا يباشر قلبي، حتى أعلم أنه لا يصيبني إلا ما كتبت لي، ورضني من المعيشة بما قسمت لي',
    'ارض عني يا الله حتى ترضى الأشياء من بعدك، حتى تفتح لي الدنيا أبوابها ويبتسم لي كل شيء',
    'اللهم ارزقنا القناعة والرضا بما قسمت لنا، واجعلنا من الشاگرين لنعمگ التي لا تعد ولا تحصى',
    'اللهم تمام الرضا والخيرة في كل اختيار',
    'اللهم ارزقنا القناعة والرضا بما قسمت لنا واجعلنا من الشاكرين',
    'اللهم ارزقني الرضا وراحة البال، اللهم لا تكسر لي ظهرا، ولا تصعب لي حاجة، ولا تعظم علي أمرا، اللهم لا تحني لي قامة، ولا تكشف لي سترا، ولا تفضح لي سرا',
    'إلهنا وخالقنا ورازقنا، توكلنا عليك فلا تكلنا إلى سواك، وهب لنا عفوا ننال به رضاك، ولا تحرمنا من رحمتك إذا ما لبت الروح نداك',
    'اللهم إني أسألك الرضا بالقضاء والقدر، وبرد العيش بعد الموت، ولذة النظر إلى وجهك، والشوق إلى لقائك في غير ضراء مضرة ولا فتنة مضلة',
  ] },
  { id: 'athar', n: 'الأثر الطيب', i: [
    'اللهم آثار خير لا تزول اللهم اجعل في قلبي نورا، وفي سمعي نورا، وفي بصري نورا، وعن يميني نورا، وعن شمالي نورا، ومن بين يدي نورا، ومن خلفي نورا، ومن فوقي نورا، ومن تحتي نورا، واجعل لي نورا، وأعظم لي نورا',
    'اللهم اجعلني ممن يدعو إليك بقوله وحسن أفعاله اللهم اجعل في لساني نورا، واجعلني من أحكم من يدعو إليك',
    'اللهم اجعلنا هادين مهتدين، غير ضالين ولا مضلين',
    'اللهم اجمع لي من الخير ما فرقته على ألسنة الداعين، ومطالب السائلين',
    'اللهم استخلفني خير استخلاف في الأرض واجعلني من',
  ] },
  { id: 'shukr', n: 'شكر النعم', i: [
    'ونسألك ألا يحول بيننا وبين النعم جحود، ألا يصرفنا ضيق الأفق عن الاستشعار أو تصدنا ضآلة الفعل عن الامتنان، ألا يدفعنا التكرار للعمى، وأن نزداد بصيرة وشكرا كلما تعاقبت علينا النعم',
    'اللهم لا تقطع عنا مألوف برك، وعوائد إحسانك، وما ربيتنا عليه من النعم، اللهم زدنا ولا تنقصنا، وأعنا على حسن شكرك وعبادتك',
    'يا رب لا أذكر منك إلا الجميل، ولا أرى منك إلا التفضيل، خيرك لي شامل، وصنعك لي كامل، ولطفك بي كافل، ونعمك عندي متصلة، وفضلك علي متواتر، صدقت رجائي، وصاحبت أسفاري، وأكرمت أحضاري، فلك الحمد حمدا متواليا، متواترا، متسقا، متسعا، مستوثقا، يدوم بدوامك لا يبيد',
    'الحمد لله بجميع محامده كلها ما علمت منها وما لم أعلم، على جميع نعمه كلها ما علمت منها وما لم أعلم، عدد خلقه كلهم ما علمت منهم وما لم أعلم الحمد لله حمد الشاكرين، والحمد لله في كل وقت وحين. الحمد لله حمدا على كل النعم.. والحمد لله على حمد النعم.. والحمد لله حمدا يليق برب النعم.. فيا ربنا لك الحمد',
    'اللهم أرنا نعمك علينا واجعلنا من الحامدين الشاكرين وألهمنا الثناء بها عليك، ربنا أعنا بنعمتك على حسن عبادتك، نعوذ بك من كفر النعمة ومن سوء استقبالها أو استعمالها، رب زدنا ولا تحرمنا ولا تقطع عنا ما أوليتنا به',
    'اللهم لك الحمد على التوفيق للحمد، ولك الشكر أن أجريت على لساننا كلمات الشكر لك، والله لا نحصي ثناء عليك، فيا أحق من ذكر، وأحق من عبد وأرأف من ملك، ويا أجود من سئل، ويا أوسع من أعطى من علينا يا مولانا بالقبول، ولا تحرمنا قربك ولا لذة مناجاتك ربنا لك الحمد على جمالك وجلالك',
    'اللهم إني أسألك تمام النعمة في الأشياء كلها.. وأسألك الشكر عليها حتى ترضى وبعد الرضا',
    'اللهم إني أسألك شكر نعمتك وحسن عبادتك، وأسألك لسانا صادقا، وقلبا سليما، وأعوذ بك من شر ما تعلم، وأسألك من خير ما تعلم، وأستغفرك مما تعلم، إنك أنت علام الغيوب، اللهم زدنا ولا تنقصنا، وأكرمنا ولا تهنا، وأعطنا ولا تحرمنا، وآثرنا ولا تؤثر علينا، وأرضنا وارض عنا، اللهم أعنا على ذكرك وشكرك وحسن عبادتك',
  ] },
  { id: 'hikma', n: 'الحكمة والبصيرة', i: [
    'اللهم اعصمني من الحيرة، واجعل بيني وبين المعرفة نسبا، وبين الصدق سببا، وحبب إلي التثبيت، وزين في عيني الإنصاف، وأودع صدري برد اليقين، واطرد عني ذل اليأس، وعرفني ما في الباطل من المذلة، وما في الجهل من القلة',
    'اللهم ارزقني السكينة وهدوء القلب، واستيعاب مجريات الأمور من حولي، والبركة والبصيرة',
    'اللهم يا نور النور أنت النور ومنك النور وإليك النور سبحانك يا من استمد النور نور من نورك ويا من أضاء الكون بشعاع من نورك ويا من استنارت القلوب بنورك أرني بنورك يا نور النور يا الله اللهم نور بصري وبصيرتي وقلبي وعزيمتي',
    'يا رب دلني على الطريق الصحيح، أرشدني إلى من هو خير لي وألهمني البعد عن من هو شر لي',
    'اللهم أرشدني بحكمتك لا بحكمتي ودلني على ما تشاء لا على ما أشاء أنت صاحب الأمر وأنا ليس لي من الأمر شيء',
    'اللهم إني أسألك الحكمة والموعظة الحسنة',
    'اللهم أنر بصري وبصيرتي وقلبي وعزيمتي بنورك يا نور النور وأنر طريقي بنورك',
    'اللهم حكمة العقل وجمال الروح وفصاحة اللسان',
    'اللهم امنحني البصيرة لأرى الأشياء كلها بشكلها الحقيقي، لا مثلما يريدها قلبي',
    'اللهم بصيرة الطريق، وعون الرفيق، وزاد الروح، وقوة الطموح، وتمهيد الدروب، وفتح الأبواب.. وألا نكون عبئا في الدنيا، بك ومنك وإليك',
    'يا رب يا معين أعني وارزقني القوة والبصيرة وألهمني يا رب رشدي وصوابي فلا حول لي ولا قوة إلا بك',
    'لا إله إلا أنت سبحانك إني كنت من الظالمين',
    'اللهم افتح لنا أبواب حكمتك، واكتب لنا من رحمتك، وامنن علينا بالحفظ والفهم، سبحانك لا علم لنا إلا ما علمتنا إنك أنت العليم الحكيم',
    'اللهم انفعنا بما علمتنا، وعلمنا ما ينفعنا، وزدني علما',
  ] },
  { id: 'ikhlas', n: 'الإخلاص', i: [
    'اللهم إنا نعوذ بك أن نشرك بك شيئا نعلمه، ونستغفرك لما لا نعلمه',
    'اللهم إنا نسألك الإخلاص في القول والعمل، وكلمة الحق في الغضب والرضا، وخشيتك في الغيب والشهادة، اللهم إنا نسألك صدق التوكل عليك، وحسن الظن بك، وارزقنا تقواك والإخلاص لك',
    'اللهم نور بالإخلاص قلوبنا، واستعمل بطاعتك أبداننا، وخلص من الفتن سرنا، وقنا شر وساوس الشيطان',
    'اللهم اجعل يقيننا أفضل اليقين، واجعل نيتنا أحسن النيات، اللهم ارزقنا الإخلاص والخشوع والهيبة والحياء والمراقبة واليقين',
    'اللهم طهر قلوبنا من النفاق، وأعمالنا من الرياء، وألسنتنا من الكذب، وأعيننا من الخيانة إنك تعلم خائنة الأعين وما تخفى الصدور',
    'اللهم اجعل عملي كله صالحا، واجعله لوجهك خالصا، ولا تجعل لأحد فيه شيئا',
    'اللهم إنا نسألك العمل الصالح وحفظه',
    'اللهم إنا نسألك صدق التوكل عليك وحسن الظن بك وارزقنا تقواك والإخلاص لك',
    'اللهم اجعل عملنا صالحا ولوجهك الكريم خالصا ولا تجعل للناس منه شيئا ولا للشيطان حظا ونصيبا وتقبله منا بقبول حسن يا رب العالمين',
    'اللهم اجعل حبك أحب الأشياء إلينا، وخشيتك أخوف الأشياء عندنا، واقطع عنا حاجات الدنيا بالشوق إلى لقائك وإذا أقررت أعين أهل الدنيا بدنياهم فأقرر أعيننا بعبادتك، يا أرحم الراحمين',
    'اللهم إن كنت فعلت ذلك ابتغاء وجهك فافرج عنا ما نحن فيه واجعلني دوما من المخلصين',
    'اللهم إنا نسألك الإخلاص في القول والعمل وكلمة الحق في الغضب والرضا وخشيتك في الغيب والشهادة',
    'اللهم ارزقنا الإخلاص في الدعوات، والقبول في الطاعات، والشكر عند الخيرات، والخشوع في الصلوات، والعفو عند العثرات',
  ] },
  { id: 'rahma', n: 'الرحمة', i: [
    'ربنا آتنا من لدنك رحمة وهيئ لنا من أمرنا رشدا، رب إني وهن العظم منى واشتعل الرأس شيبا ولم أكن بدعائك رب شقيا',
    'اللهم إنا نستمطر من يمينك الملأى سحاء الليل والنهار من الرحمات والبركات ومن الأعطيات والأنوار ما تملأ به حياتنا جمالا وسعادة ورضا ويقينا وراحة ورحمة وسكنا وسكينة وهدوءا وهدى وغنى وبركة',
    'يا رب هب لي من عندك رحمة تغنيني عن كل شيء فإنه لا يعجزك شيء، يا بديع السماوات والأرض لا إله إلا أنت سبحانك إنك أنت الوهاب',
    'ربي أسألك بحق محمد رسول رحمتك إلى الخلق، ونور تكوينك للوجود، وبركة أصقاع الأرض، أن تعافينا وترحمنا وتشملنا بلطفك، وبتيسير أمرك، وتهوين قضائك يا مالك الفلاح ومجري الرياح',
    'اللهم غيثا من البشارات التي نحب والأيام التي تسر والرحمات التي تتوالى والعافية التي ننعم بها',
    'اللهم لك الحمد كله، اللهم لا قابض لما بسطت، ولا مقرب لما باعدت، ولا مباعد لما قربت، ولا معطي لما منعت، ولا مانع لما أعطيت اللهم ابسط علينا من بركاتك ورحمتك وفضلك',
    'اللهم ارحمنا إذا أتانا اليقين، وعرق منا الجبين، وكثر الأنين والحنين',
    'اللهم ارحمنا إذا اشتدت الكربات، وتوالت الحسرات، وأطبقت الروعات، وفاضت العبرات، وتكشفت العورات، وتعطلت القوى والقدرات',
    'اللهم ارحمنا إذا أقمنا للسؤال، وخاننا المقال، ولم ينفع جاه ولا مال ولا عيال، وقد حال الحال، وليس إلا فضل الكبير المتعال',
    'اللهم ارحمنا إذا نسي اسمنا، ودرس رسمنا، وأحاط بنا قسمنا ووسعنا',
    'اللهم إنا نسألك أن ترحمنا وتكشف ما بنا من ضر وأن تزيل همومنا وتذهب وحشة قلوبنا',
    'اللهم أسألك بأنك الرحمة كلها، الرحمن الرحيم، مجيب الدعاء الفتاح العليم، ارحمنا رحمة لا نضل بعدها، واغفر لنا مغفرة لا نتيه إثرها، ونولنا عونك وهداك على أمورنا كلها، إنك عظيم الرجاء',
  ] },
  { id: 'saa', n: 'السعة', i: [
    'يا من لا يعجزه أمر ولا يمنعه تدبير ولا يشتته تفكير ولا يثقله هم.. امنحنا حولا من حولك وقوة من لدنك وسعة نلوذ بها ويقينا نتبصر به في عز تخبطاتنا وضياعنا؛ دلنا',
    'اللهم السعة والمتسع والرحابة واليسر والبشائر التي ننتظر',
    'اللهم السكينة في المسكن، والربيع في العمر، وطيب الحياة، ونرجوك -يا واسع- السعة التي نجد معها الانشراح في أمورنا كلها',
    'اللهم أبدل قلقي سكينة وهمي انشراحا وسخطي رضا وخوفي طمأنينة وعجزي قدرة وحزني فرحا وضيقي سعة وعسري يسرا وضعفي قوة',
    'اللهم اهدنا بهدايتك، وارحمنا برحمتك، وانقلنا من دائرة سخطك إلى دائرة رضاك، ومن المعصية إلى الطاعة، ومن الكفران إلى الشكران، ومن الضيق إلى السعة، واجعل القرآن الكريم ربيع قلوبنا، وجلاء همنا وحزننا، واجعله حجة لنا لا علينا، وعلمنا منه ما ينفعنا وانفعنا بما علمتنا، وزدنا علما',
    'يا رب وأنت رب السعة، اجعلنا على سعة من عندك يا قادر',
    'اللهم السعة والسلام أينما اتجهنا',
    'يا رب أن تتوالى علينا المسرات دوما وتمتد البركة والرحابة والسعة في ميادين أعمارنا وتتبارك حظوظنا وتستقر الطمأنينة في صدورنا أبد الدهر',
    'اللهم السعة والانشراح والأنس بك',
    'رب السعة والاتساع ضعني حيث أنتمي وأحب',
    'لا تحملنا يا الله من الضيق والتعب والأوجاع ما لا قدرة لأرواحنا على حمله، اللهم السعة',
    'نرجوك يا واسع السعة التي نجد معها الانشراح في أمورنا كلها. اللهم إنا نسألك حياة سعيدة ورفقة صالحة ونهاية عمر جميلة ورزقا مباركا وأدعية مستجابة',
    'اللهم السعة والمتسع والرحابة واليسر',
    'اللهم أعطنا السعة في الرزق والأمن والأمان في الوطن والإخلاص والثبات في الدين اللهم السعة والمتسع والانشراح، في البال والنفس والخاطر',
    'السعة.. يا وهاب السعة',
    'أسأل الله أن يرزقني السعة، السعة في قلبي وفي عيني، أن يرزقني البصيرة لرؤية براح الكون، وألا يضيق علي صدري ولا تتحدد رؤيتي فلا تبصر النعم والوسع في السماء والعالم',
    'اللهم السعة في جميع أمورنا.. اللهم ارزقني سعة الحياة وسعة النفس وسعة الرزق',
    'اللهم السعة والتوسع والمتسع لقبور موتانا',
  ] },
  { id: 'qalb', n: 'سلامة القلب', i: [
    'اللهم إني أسألك الثبات في الأمر والعزيمة على الرشد وأسألك موجبات رحمتك وعزائم مغفرتك وأسألك شكر نعمتك وحسن عبادتك وأسألك قلبا سليما ولسانا صادقا وأسألك من خير ما تعلم وأعوذ بك من شر ما تعلم وأستغفرك لما تعلم إنك أنت علام الغيوب',
    'اللهم إني أعوذ بك من شر قلبي',
    'اللهم اجعل في قلبي نورا',
    'اللهم اجعل القرآن العظيم ربيع قلبي ونور صدري',
    'اللهم أصلح قلبي وأذهب قسوته وطهره من النفاق والرياء واجعله قلبا مطمئنا لينا مخبتا منيبا ولا تنزع منه الرحمة يا رب العالمين',
    'اللهم يا مقلب القلوب ثبت قلبي على دينك، ويا مصرف القلوب صرف قلبي على طاعتك، اللهم أصلح قلبي وعملي، اللهم طهر قلبي من كل خلق لا يرضيك، اللهم طهر قلبي من الغل والحقد والحسد والكبر، اللهم طهر قلبي من كل سوء، ومن كل أذى، ومن كل داء',
    'اللهم مجيئا، كمجيء إبراهيم، بقلب سليم',
    'اللهم طهر قلبي من كل خلق لا يرضيك، اللهم طهر قلبي من الغل والحقد والحسد والكبر، اللهم طهر قلبي من كل سوء، من كل أذى، من كل داء',
    'رب أصلح لي قلبي',
    'اللهم أصلح قلبي وعملي، اللهم طهر قلبي من كل داء، اللهم طهر قلبي وجوارحي من كل سوء، اللهم طهر قلبي وجوارحي من كل ما يغضبك',
    'اللهم إنا نسألك من الخير كله عاجله وآجله، ما علمنا منه وما لم نعلم، ونعوذ بك من الشر كله، عاجله وآجله، ما علمنا منه وما لم نعلم',
    'ربنا اغفر لنا ولوالدينا ولوالد والدينا، ولمن لهم حقوق علينا.. اللهم ارحم ضعفنا، واقض حوائجنا وفرج كروبنا، واقض ديوننا، وفرج همومنا، واصرف عنا سوء المحن ما ظهر منها وما بطن',
  ] },
  { id: 'qadr', n: 'ليلة القدر', i: [
    'اللهم امسح عن الجبين الحزن والتعب، فإن الظلام قد طال وكثرت السحب. اللهم ارزقنا نصرا نمحو به بؤسنا، وعزا نطهر به غمنا، اللهم لا تردنا إلا وقد عزت بذكرك ألسنتنا، وطهرت من الذنوب أبداننا، وملأت بالهدى قلوبنا، وشرحت بالإسلام صدورنا، وأقررت برضاك عيوننا، واستخدمت لدينك أرواحنا وأبداننا... اللهم قومنا إذا اعوججنا، وأعنا إذا استقمنا، وأعطنا رضا لا سخط بعده، وهدى لا ضلال بعده، وعلما لا جهل بعده، وغنى لا فقر بعده، واجعلنا في كنفك وإنعامك، وعطائك وإحسانك',
    'اللهم إن كانت هذه ليلة القدر فاقسم لي فيها خير ما قسمت، واختم لي في قضائك خير ما ختمت، واختم لي بالسعادة فيما ختمت... اللهم افتح لي في هذه الليلة باب كل خير فتحته لأحد من خلقك وأوليائك وأهل طاعتك ولا تسده عني وارزقني رزقا تغيثني به من رزقك الطيب الحلال',
    'اللهم ما قسمت في هذه الليلة المباركة من خير وعافية وصحة وسلامة وسعة رزق فاجعل لي منه نصيبا، وما أنزلت فيها من سوء وبلاء وشر وفتنة فاصرفه عني وعن جميع المسلمين',
    'اللهم ارزقني رزقا واسعا حلالا طيبا، واستجب دعائي من غير رد، وأعوذ بك من الفضيحتين؛ الفقر والدين، اللهم يا رازق السائلين، ويا راحم المساكين، يا ذا القوة المتين، ويا ولي المؤمنين، ويا خير الناصرين، يا غياث المستغيثين، ارزقني يا أرحم الراحمين',
    'اللهم قد وقفنا بين يديك خائفين فاغفر لنا يا الله.. اللهم إنا نسألك في هذه الليلة المباركة أن تعتق رقابنا من النار.. اللهم إنك عفو تحب العفو فاعف عنا.. اللهم إنا نسألك الجنة وما يقرب إليها من قول وعمل، ونعوذ بك من النار وما يقرب إليها من قول وعمل',
    'اللهم تقبل منا الصيام والقيام، وتجاوز عنا. اللهم اجعلنا ممن تقبلت منهم الصيام والقيام.. اللهم أعد رمضان علينا أعواما عديدة وأزمانا مديدة.. اللهم اجعلنا من أهل القرآن الذين هم أهلك وخاصتك',
    'اللهم إنا نسألك في هذه الليلة المباركة باسمك العظيم الأعظم، الذي إذا دعيت به أجبت، وإذا سئلت به أعطيت، وبأسمائك الحسنى كلها ما علمنا منها وما لم نعلم، أن ترفع عنا البلاء والغلاء، وأن تقضي حوائجنا، وتفرج كروبنا، وتغفر ذنوبنا، وتستر عيوبنا، وتتوب علينا، وتعافينا وتعفو عنا، وتصلح أهلينا وذرياتنا، وتحفظنا بعين رعايتك، وتحسن عاقبتنا في الأمور كلها، وترحمنا برحمتك الواسعة، رحمة تغنينا بها عمن سواك',
    'اللهم إنك عفو تحب العفو فاعف عني',
  ] },
];
var DUA_BOOK_SOURCE = { b: 'فإنك بأعيننا', n: 'أدعية مختارة' };
if (typeof module !== 'undefined') module.exports = { DUA_BOOK: DUA_BOOK, DUA_BOOK_SOURCE: DUA_BOOK_SOURCE };
